pg_json_repo!(
    PgWearableReadingRecordRepository,
    "wearable_reading_records"
);
pg_json_repo!(PgWearableAlertRecordRepository, "wearable_alert_records");
pg_json_repo!(PgWearableAlertRuleRepository, "wearable_alert_rules");
pg_json_repo!(
    PgTelehealthSessionRecordRepository,
    "telehealth_session_records"
);

// Round 6: shape-mismatch domains (legacy structs differ from existing typed
// entities). Persisted losslessly as JSON under distinct table names.
pg_json_repo!(PgEPrescriptionV2Repository, "e_prescription_v2_records");
pg_json_repo!(PgDrugInteractionCheckRepository, "drug_interaction_checks");
pg_json_repo!(PgLabTrendResultRepository, "lab_trend_results");
pg_json_repo!(PgLabResultSubmissionRepository, "lab_result_submissions");

// Round 7: SOAP clinical notes (no prior repository existed).
pg_json_repo!(PgSoapNoteRecordRepository, "soap_note_records");

// Phase 4.3: per-facility CDS thresholds + CDS audit trail.
pg_json_repo!(PgCdsThresholdConfigRepository, "cds_threshold_configs");
pg_json_repo!(PgCdsAuditEntryRepository, "cds_audit_entries");

// Phase 33: offline-sync device registry.
pg_json_repo!(PgSyncDeviceRepository, "sync_devices");

// Horizon HZ-023: real stores replacing fabricated literals.
pg_json_repo!(PgMessageRepository, "messages");
pg_json_repo!(PgSymptomEntryRepository, "symptom_entries");
pg_json_repo!(PgBarcodeScanRepository, "barcode_scans");

// Final durability sweep (migration 20260811000002): the last process-memory
// clinical maps. The first three are shape-mismatch domains whose typed tables
// require columns the API types do not carry — see the migration for why.
pg_json_repo!(
    PgBloodTypeScreenRecordRepository,
    "blood_type_screen_records"
);
pg_json_repo!(
    PgTransfusionEventRecordRepository,
    "transfusion_event_records"
);
pg_json_repo!(PgEPrescriptionRecordRepository, "e_prescription_records");
